public Object process(TFMInventDimFieldName _fieldName, ItemId _itemId)
{
    TFMInventDimensionSetupContract contract = next process(_fieldName, _itemId);
    InventTable inventTable = InventTable::find(_itemId);
    TFMInventDimSetup inventDimSetup = TFMInventDimSetup::Construct(inventTable);
    if( _fieldName == fieldStr(InventDim, WMSLocationId))
    {
        contract.parmActive(inventDimSetup.registerWMSLocation() && !inventDimSetup.registerLicensePlate());
    }
    else if (_fieldName == fieldStr(InventDim, LicensePlateId))
    {            
        contract.parmActive(inventDimSetup.registerLicensePlate());
    }
    InventDim inventDim = context.getTableFromAnyBlock(tableStr(InventDim));
    InventBatch     batchTbl;
    batchTbl = InventBatch::find(inventDim.inventBatchId, _itemId);
    //Batch Expiration with condition: if (((iTbl.BatchNumGroupId && InventNumGroup::find(iTbl.BatchNumGroupId).MobInclExpectedDate)) && dimSetup.registerBatchID() && (!batchTbl || (!batchTbl.expDate)))
    if (((inventTable.BatchNumGroupId && InventNumGroup::find(inventTable.BatchNumGroupId).MobInclExpectedDate)) && inventDimSetup.registerBatchID() && (!batchTbl || (!batchTbl.expDate)))
    {
        contract.parmExpDateActive(true);
    }

    return contract;
}
